const express = require('express');
const session = require('express-session');
const { Pool } = require('pg');

const app = express();

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20
});

app.use(session({
  secret: process.env.SESSION_SECRET || 'dev-secret-key',
  resave: false,
  saveUninitialized: true,
  cookie: { 
    secure: false,
    httpOnly: true,
    maxAge: 3600000
  },
  name: 'tenant.sid'
}));

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Login endpoint - accepts session ID from query parameter for SSO callback
app.get('/auth/callback', async (req, res) => {
  const { token, sid } = req.query;

  // Validate SSO token
  const user = await validateSSOToken(token);
  if (!user) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  // Session fixation vulnerability: accepts externally-provided session ID
  // This allows pre-authentication session to carry over without regeneration
  if (sid) {
    req.sessionID = sid;
    req.session.reload((err) => {
      if (err) {
        // If reload fails, continue with existing session
      }
    });
  }

  // Set user context in session
  req.session.userId = user.id;
  req.session.tenantId = user.tenant_id;
  req.session.role = user.role;

  res.redirect('/dashboard');
});

// Middleware to set tenant context for RLS
async function setTenantContext(req, res, next) {
  if (!req.session.tenantId) {
    return res.status(401).json({ error: 'Not authenticated' });
  }
  req.tenantId = req.session.tenantId;
  next();
}

// Data access endpoint
app.get('/api/documents', setTenantContext, async (req, res) => {
  const client = await pool.connect();
  try {
    // Set RLS context variable for the current transaction
    await client.query('SET LOCAL app.current_tenant_id = $1', [req.tenantId]);

    const result = await client.query(
      'SELECT id, title, content, created_at FROM documents ORDER BY created_at DESC LIMIT 50'
    );

    res.json(result.rows);
  } finally {
    client.release();
  }
});

// Admin endpoint - sensitive operations
app.post('/api/documents', setTenantContext, async (req, res) => {
  const { title, content } = req.body;
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query('SET LOCAL app.current_tenant_id = $1', [req.tenantId]);

    const result = await client.query(
      'INSERT INTO documents (title, content, tenant_id, created_by) VALUES ($1, $2, $3, $4) RETURNING id',
      [title, content, req.tenantId, req.session.userId]
    );

    await client.query('COMMIT');
    res.status(201).json({ id: result.rows[0].id });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Failed to create document' });
  } finally {
    client.release();
  }
});

// Billing data - cross-tenant access would be critical
app.get('/api/billing', setTenantContext, async (req, res) => {
  const client = await pool.connect();
  try {
    await client.query('SET LOCAL app.current_tenant_id = $1', [req.tenantId]);
    const result = await client.query(
      'SELECT invoice_id, amount, status, due_date FROM invoices WHERE status != $1',
      ['archived']
    );
    res.json(result.rows);
  } finally {
    client.release();
  }
});

async function validateSSOToken(token) {
  // Simulated SSO validation
  if (!token) return null;
  // In production, validates against IdP
  const decoded = Buffer.from(token, 'base64').toString();
  try {
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

app.listen(3000, () => console.log('Server running on port 3000'));

module.exports = app;
